import { spawnSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';

/**
 * The prior-contract upgrade fixture (S09.7): a production app generated by
 * the LAST PUBLISHED core, moved onto the archives under test.
 *
 *   node scripts/upgrade-smoke.mjs <new-artifacts> [old core version]
 *
 * Proves three things without services: the unmigrated app gets the selected
 * migration diagnostics (no declaration → refused before any module import;
 * the old `@tulipes/core/db` specifier → told where the provider went; the
 * old type import → "no exported member"), and the app migrated exactly as
 * MIGRATING.md says installs, typechecks and describes itself offline.
 * TULIPES_OLD_CORE=<archive> uses a local old archive instead of the registry.
 */
const [artifactPath, oldVersion = '0.9.0-rc.3'] = process.argv.slice(2);
if (!artifactPath) throw new Error('Usage: upgrade-smoke.mjs <artifacts> [old core version]');
const artifacts = resolve(artifactPath);
const workspace = mkdtempSync(join(tmpdir(), 'tulipes-upgrade-'));
const scripts = import.meta.dirname;
const logs = resolve('reports', 'upgrade-smoke');
mkdirSync(logs, { recursive: true });
let step = 0;
function run(command, args, cwd, env = process.env, { expectFailure } = {}) {
  const result = spawnSync(command, args, { cwd, env, encoding: 'utf8', timeout: 180_000 });
  const file = join(logs, `${String(++step).padStart(2, '0')}-${command.split('/').at(-1)}.log`);
  const output = (result.stdout ?? '') + (result.stderr ?? '');
  writeFileSync(file, `$ ${command} ${args.join(' ')}\n\n` + output);
  const failed = result.status !== 0;
  if (failed !== Boolean(expectFailure)) throw new Error(`${command} ${args.join(' ')} ${failed ? 'failed' : 'unexpectedly succeeded'}; see ${file}\n${result.error ?? ''}\n${result.stderr ?? ''}`);
  return (result.stdout ?? '') + (result.stderr ?? '');
}
const install = (cwd, env = process.env) => run('pnpm', ['install', '--no-frozen-lockfile'], cwd, env);
// MIGRATING.md, the package-manager step: an app generated by a yarn-era core
// becomes a pnpm workspace before anything else is installed under it.
function toPnpm(dir) {
  const file = join(dir, 'package.json');
  const pkg = readJson(file);
  const { workspaces, resolutions, ...rest } = pkg;
  writeJson(file, { ...rest, packageManager: 'pnpm@10.28.0', ...(resolutions && { pnpm: { ...rest.pnpm, overrides: { ...rest.pnpm?.overrides, ...resolutions } } }) });
  if (workspaces) writeFileSync(join(dir, 'pnpm-workspace.yaml'), 'packages:\n' + workspaces.map(glob => `  - ${glob}\n`).join(''));
  rmSync(join(dir, '.yarnrc.yml'), { force: true });
}
const readJson = file => JSON.parse(readFileSync(file, 'utf8'));
const writeJson = (file, value) => writeFileSync(file, JSON.stringify(value, null, 2) + '\n');

try {
  run(process.execPath, [join(scripts, 'artifacts.mjs'), 'verify', artifacts], workspace);
  const manifest = readJson(join(artifacts, 'manifest.json'));
  const resolutions = Object.fromEntries(manifest.packages.map(pkg => [pkg.name, 'file:' + join(artifacts, pkg.file)]));
  const provider = manifest.packages.find(pkg => pkg.name === '@tulipes/mongoose');
  const queues = manifest.packages.find(pkg => pkg.name === '@tulipes/bullmq');
  const sockets = manifest.packages.find(pkg => pkg.name === '@tulipes/socket.io');
  const cli = manifest.packages.find(pkg => pkg.name === '@tulipes/cli');
  if (!provider || !queues || !sockets || !cli) throw new Error('The artifacts under test must include the mongoose, bullmq and socket.io providers and the cli');

  // 1. The old world: the last published core generates a production app.
  const oldRoot = join(workspace, 'old-cli');
  mkdirSync(oldRoot);
  let oldCore = process.env.TULIPES_OLD_CORE;
  if (!oldCore) {
    run('npm', ['pack', `@tulipes/core@${oldVersion}`, '--pack-destination', oldRoot], oldRoot);
    oldCore = join(oldRoot, readdirSync(oldRoot).find(file => file.endsWith('.tgz')));
  }
  writeJson(join(oldRoot, 'package.json'), { private: true, packageManager: 'pnpm@10.28.0', dependencies: { '@tulipes/core': 'file:' + resolve(oldCore) } });
  install(oldRoot);
  const oldBin = join(oldRoot, 'node_modules/@tulipes/core/dist/cli/bin.js'); // pre-split core still ships the CLI
  const generatedBy = readJson(join(oldRoot, 'node_modules/@tulipes/core/package.json')).version;
  const app = join(workspace, 'app');
  run(process.execPath, [oldBin, 'init', app, '--preset', 'production'], workspace);
  const pkgFile = join(app, 'package.json');
  const before = readJson(pkgFile);
  if (before.tulipes?.providers) throw new Error(`core ${generatedBy} already generates a provider declaration; pick an older baseline`);
  if (!existsSync(join(app, 'modules/users/models/user.model.ts')) || !readFileSync(join(app, 'modules/users/models/user.model.ts'), 'utf8').includes('@tulipes/core/db')) {
    throw new Error('The old starter does not use the pre-extraction contract this fixture upgrades from');
  }

  // 2. New core installed under the old app, nothing else changed — except the
  // CLI devDependency, which the split makes a prerequisite for every app
  // command and which MIGRATING.md lists as step one.
  writeJson(pkgFile, { ...before, devDependencies: { ...before.devDependencies, '@tulipes/cli': '^' + cli.version }, resolutions: { ...before.resolutions, ...resolutions } });
  toPnpm(app);
  const env = { ...process.env, APP_ENV: 'production', LOG_FILE: 'false', LOG_CONSOLE: 'false', PORT: '0',
    MONGO_URI: 'mongodb://127.0.0.1:1/unreachable', REDIS_URL: 'redis://127.0.0.1:1',
    JWT_ACCESS_SECRET: randomBytes(32).toString('hex'), JWT_REFRESH_SECRET: randomBytes(32).toString('hex'),
    AUTH_ADMIN_EMAIL: 'upgrade@example.test', AUTH_ADMIN_PASSWORD: randomBytes(32).toString('hex') };
  install(app, env);
  const newBin = join(app, 'node_modules/@tulipes/cli/dist/bin.js'); // installed by the migration below
  const guard = join(app, 'offline-guard.mjs');
  writeFileSync(guard, `import { Socket } from 'node:net';\nSocket.prototype.connect = function () { throw new Error('a connection was attempted'); };\n`);
  writeFileSync(join(app, 'try-boot.mjs'), `
    import { boot } from '@tulipes/core/boot';
    try { const handle = await boot({ rootDir: import.meta.dirname, mode: 'script', handleSignals: false }); await handle.shutdown(); }
    catch (error) { console.error(error.message); process.exit(3); }
  `);
  const tryBoot = () => run(process.execPath, ['--import', guard, '--import', 'tsx', 'try-boot.mjs'], app, env, { expectFailure: true });

  // 2a. No declaration: refused before any module code is imported, never connecting.
  let output = tryBoot();
  for (const expected of ['Boot aborted during "providers"', '[auth] requires capability "models" (has models/ files)', '[users] requires capability "models"', '[users] requires capability "queues" (has queues/ files)', '[users] requires capability "sockets" (has sockets/ files)', 'declares no provider for it']) {
    if (!output.includes(expected)) throw new Error(`Unmigrated app did not report: ${expected}\n${output}`);
  }
  if (output.includes('a connection was attempted')) throw new Error('Unmigrated app attempted a connection');

  // 2b. The old subpath declared as the provider: told where it went.
  writeJson(pkgFile, { ...readJson(pkgFile), tulipes: { providers: { models: '@tulipes/core/db', queues: '@tulipes/core/queues', sockets: '@tulipes/core/sockets' } } });
  output = tryBoot();
  if (!output.includes('"@tulipes/core/db" no longer contains the Mongoose provider') || !output.includes('@tulipes/mongoose')) throw new Error('Old subpath declaration did not get the migration diagnostic\n' + output);
  if (!output.includes('"@tulipes/core/queues" no longer contains the BullMQ provider') || !output.includes('@tulipes/bullmq')) throw new Error('Old queues subpath declaration did not get the migration diagnostic\n' + output);
  if (!output.includes('"@tulipes/core/sockets" no longer contains the Socket.IO provider')) throw new Error('Old sockets subpath declaration did not get the migration diagnostic\n' + output);
  if (output.includes('a connection was attempted')) throw new Error('Old subpath declaration attempted a connection');

  // 2c. The old type import fails to typecheck with a message naming the
  // member — and, with no provider in the compilation, ctx.models has no
  // members at all: core's declarations carry nothing of Mongoose.
  output = run(join(app, 'node_modules/.bin/tsc'), ['--noEmit', '-p', 'tsconfig.json'], app, env, { expectFailure: true });
  if (!/Module '"@tulipes\/core\/db"' has no exported member 'ModelDef'/.test(output)) throw new Error('Old ModelDef import did not fail with "no exported member"\n' + output);
  if (!/Property 'get' does not exist on type 'ModelsCapability'/.test(output)) throw new Error('Core-only ModelsCapability unexpectedly exposes get()\n' + output);
  if (!/Module '"@tulipes\/core\/queues"' has no exported member 'QueueRegistry'/.test(output)) throw new Error('Old QueueRegistry import did not fail with "no exported member"\n' + output);
  if (!/Module '"@tulipes\/core\/sockets"' has no exported member 'SocketRegistry'/.test(output)) throw new Error('Old SocketRegistry import did not fail with "no exported member"\n' + output);

  // 3. Apply MIGRATING.md, step by step.
  const migrated = readJson(pkgFile);
  migrated.tulipes = { providers: { models: '@tulipes/mongoose', queues: '@tulipes/bullmq', sockets: '@tulipes/socket.io' } };
  migrated.dependencies = { ...migrated.dependencies, '@tulipes/mongoose': '^' + provider.version, '@tulipes/bullmq': '^' + queues.version, '@tulipes/socket.io': '^' + sockets.version };
  writeJson(pkgFile, migrated);
  let rewrittenImports = 0, rewrittenManifests = 0;
  for (const module of readdirSync(join(app, 'modules'))) {
    const dir = join(app, 'modules', module);
    for (const sub of ['models', 'bootstrap', 'queues', 'sockets']) {
      if (!existsSync(join(dir, sub))) continue;
      for (const file of readdirSync(join(dir, sub))) {
        const path = join(dir, sub, file);
        const source = readFileSync(path, 'utf8');
        const next = source.replaceAll('from "@tulipes/core/db"', 'from "@tulipes/mongoose"').replaceAll('from "@tulipes/core/queues"', 'from "@tulipes/bullmq"').replaceAll('from "@tulipes/core/sockets"', 'from "@tulipes/socket.io"');
        if (next !== source) { writeFileSync(path, next); rewrittenImports++; }
      }
    }
    const needsModels = existsSync(join(dir, 'models')) || existsSync(join(dir, 'bootstrap'));
    const needsQueues = existsSync(join(dir, 'queues'));
    const needsSockets = existsSync(join(dir, 'sockets'));
    if (needsModels || needsQueues || needsSockets) {
      const file = join(dir, 'package.json');
      const pkg = readJson(file);
      pkg.dependencies = { ...pkg.dependencies, ...(needsModels && { '@tulipes/mongoose': '^' + provider.version }), ...(needsQueues && { '@tulipes/bullmq': '^' + queues.version }), ...(needsSockets && { '@tulipes/socket.io': '^' + sockets.version }) };
      writeJson(file, pkg);
      rewrittenManifests++;
    }
  }
  if (rewrittenImports === 0 || rewrittenManifests === 0) throw new Error('Migration touched nothing');
  install(app, env);
  for (const script of ['sync', 'typecheck']) run('pnpm', [script], app, env);
  run(process.execPath, ['--import', guard, newBin, 'routes'], app, env);
  run(process.execPath, ['--import', guard, newBin, 'spec', '--openapi', 'docs/openapi.json', '--postman', 'docs/collection.json'], app, env);
  const spec = readJson(join(app, 'docs/openapi.json'));
  if (!spec.paths['/api/v1/auth/login']) throw new Error('Migrated app lost its routes');
  // The migrated app now reaches the provider: with an unreachable database it
  // must fail in the provider, after the declaration phase, not before it.
  output = tryBoot();
  if (output.includes('declares no provider') || output.includes('no longer contains')) throw new Error('Migrated app still gets migration diagnostics\n' + output);
  if (!/Boot aborted during "providers"/.test(output) || !/database connection failed/.test(output)) throw new Error('Migrated app did not reach the Mongoose provider\n' + output);

  writeJson(join(logs, 'summary.json'), { generatedBy, upgradedTo: Object.fromEntries(manifest.packages.map(pkg => [pkg.name, pkg.version])), rewrittenImports, rewrittenManifests });
  console.log(`upgrade: production app generated by core ${generatedBy} refused with migration diagnostics, then installed, typechecked and described itself offline on ${manifest.packages.map(pkg => `${pkg.name}@${pkg.version}`).join(', ')} (${rewrittenImports} imports, ${rewrittenManifests} manifests rewritten)`);
} finally {
  rmSync(workspace, { recursive: true, force: true });
}
